using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Domain;

public sealed class LoyaltyDiscountPolicyTests
{
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 3_001, 150)]
    [InlineData(LoyaltyTier.Silver, 3_007, 300)]
    [InlineData(LoyaltyTier.Gold, 3_007, 451)]
    [InlineData(LoyaltyTier.Platinum, 3_007, 601)]
    [InlineData(LoyaltyTier.Gold, 10_000, 1_500)]
    [InlineData(LoyaltyTier.Platinum, 10_001, 2_000)]
    public void LoyaltyPartRoundsDownToTheCent(LoyaltyTier tier, int subtotalCents, int expectedCents) =>
        Assert.Equal(expectedCents, LoyaltyDiscountPolicy.LoyaltyCents(subtotalCents, tier));

    [Theory]
    [InlineData(1)]
    [InlineData(7)]
    [InlineData(100)]
    public void NoLoyaltyPartBelowTheMinimumSubtotal(int subtotalCents) =>
        Assert.Equal(0, LoyaltyDiscountPolicy.LoyaltyCents(subtotalCents, LoyaltyTier.Gold));
}

